示例：实现一个包含RelativeContainer的Row组件，其中RelativeContainer内部包含一个红色矩形。红色矩形的顶部、底部、左侧和右侧分别与RelativeContainer的顶部、底部、左侧和右侧对齐，并通过垂直偏移使其相对于父容器的顶部和底部偏移30%。RelativeContainer的宽度为300，高度为300，左边距为50，并带有宽度为2的蓝色边框。整个Row的高度为100%。
@Entry
@Component
struct Index {
  build() {
    Row() {
      RelativeContainer() {
        // 创建一个宽度为100，高度为100的红色矩形
        Row().width(100).height(100)
          .backgroundColor("#FF3333")
          .alignRules({
            // 矩形的顶部与父容器的顶部对齐
            top: {anchor: "__container__", align: VerticalAlign.Top},
            // 矩形的底部与父容器的底部对齐
            bottom: {anchor: "__container__", align: VerticalAlign.Bottom},
            // 矩形的左侧与父容器的左侧对齐
            left: {anchor: "__container__", align: HorizontalAlign.Start},
            // 矩形的右侧与父容器的右侧对齐
            right: {anchor: "__container__", align: HorizontalAlign.End},
            // 设置矩形的垂直偏移，使其相对于父容器的顶部和底部偏移30%
            bias: {vertical: 0.3}
          })
          .id("row1")
      }
      .width(300).height(300)
      .margin({left: 50}) // 设置RelativeContainer的左边距为50
      .border({width:2, color: "#6699FF"}) // 为RelativeContainer添加一个宽度为2的蓝色边框
    }
    .height('100%') // 设置Row的高度为100%
  }
}

示例：实现一个包含多个链布局的相对容器组件，展示不同链布局样式（SPREAD、SPREAD_INSIDE、PACKED）的效果。每个链布局包含三个子组件，通过alignRules属性设置子组件之间的相对位置关系。
@Entry
@Component
struct Index {
  build() {
    Row() {
      RelativeContainer() {
        // 第一个链布局：SPREAD
        Row(){Text('row1')}.justifyContent(FlexAlign.Center)
          .width(80).height(80)
          .backgroundColor("#FF3333")
          .alignRules({
            left: {anchor: "__container__", align: HorizontalAlign.Start}, // 左对齐容器
            right: {anchor: "row2", align : HorizontalAlign.Start}, // 右对齐row2的左侧
            top: {anchor: "__container__", align: VerticalAlign.Top} // 顶部对齐容器
          })
          .id("row1")
          .chainMode(Axis.Horizontal, ChainStyle.SPREAD) // 设置水平方向的SPREAD链布局

        Row(){Text('row2')}.justifyContent(FlexAlign.Center)
          .width(80).height(80)
          .backgroundColor("#FFCC00")
          .alignRules({
            left: {anchor: "row1", align: HorizontalAlign.End}, // 左对齐row1的右侧
            right: {anchor: "row3", align : HorizontalAlign.Start}, // 右对齐row3的左侧
            top: {anchor: "row1", align: VerticalAlign.Top} // 顶部对齐row1的顶部
          })
          .id("row2")

        Row(){Text('row3')}.justifyContent(FlexAlign.Center)
          .width(80).height(80)
          .backgroundColor("#FF6633")
          .alignRules({
            left: {anchor: "row2", align: HorizontalAlign.End}, // 左对齐row2的右侧
            right: {anchor: "__container__", align : HorizontalAlign.End}, // 右对齐容器的右侧
            top: {anchor: "row1", align: VerticalAlign.Top} // 顶部对齐row1的顶部
          })
          .id("row3")

        // 第二个链布局：SPREAD_INSIDE
        Row(){Text('row4')}.justifyContent(FlexAlign.Center)
          .width(80).height(80)
          .backgroundColor("#FF3333")
          .alignRules({
            left: {anchor: "__container__", align: HorizontalAlign.Start}, // 左对齐容器
            right: {anchor: "row5", align : HorizontalAlign.Start}, // 右对齐row5的左侧
            center: {anchor: "__container__", align: VerticalAlign.Center} // 垂直居中对齐容器
          })
          .id("row4")
          .chainMode(Axis.Horizontal, ChainStyle.SPREAD_INSIDE) // 设置水平方向的SPREAD_INSIDE链布局

        Row(){Text('row5')}.justifyContent(FlexAlign.Center)
          .width(80).height(80)
          .backgroundColor("#FFCC00")
          .alignRules({
            left: {anchor: "row4", align: HorizontalAlign.End}, // 左对齐row4的右侧
            right: {anchor: "row6", align : HorizontalAlign.Start}, // 右对齐row6的左侧
            top: {anchor: "row4", align: VerticalAlign.Top} // 顶部对齐row4的顶部
          })
          .id("row5")

        Row(){Text('row6')}.justifyContent(FlexAlign.Center)
          .width(80).height(80)
          .backgroundColor("#FF6633")
          .alignRules({
            left: {anchor: "row5", align: HorizontalAlign.End}, // 左对齐row5的右侧
            right: {anchor: "__container__", align : HorizontalAlign.End}, // 右对齐容器的右侧
            top: {anchor: "row4", align: VerticalAlign.Top} // 顶部对齐row4的顶部
          })
          .id("row6")

        // 第三个链布局：PACKED
        Row(){Text('row7')}.justifyContent(FlexAlign.Center)
          .width(80).height(80)
          .backgroundColor("#FF3333")
          .alignRules({
            left: {anchor: "__container__", align: HorizontalAlign.Start}, // 左对齐容器
            right: {anchor: "row8", align : HorizontalAlign.Start}, // 右对齐row8的左侧
            bottom: {anchor: "__container__", align: VerticalAlign.Bottom} // 底部对齐容器
          })
          .id("row7")
          .chainMode(Axis.Horizontal, ChainStyle.PACKED) // 设置水平方向的PACKED链布局

        Row(){Text('row8')}.justifyContent(FlexAlign.Center)
          .width(80).height(80)
          .backgroundColor("#FFCC00")
          .alignRules({
            left: {anchor: "row7", align: HorizontalAlign.End}, // 左对齐row7的右侧
            right: {anchor: "row9", align : HorizontalAlign.Start}, // 右对齐row9的左侧
            top: {anchor: "row7", align: VerticalAlign.Top} // 顶部对齐row7的顶部
          })
          .id("row8")

        Row(){Text('row9')}.justifyContent(FlexAlign.Center)
          .width(80).height(80)
          .backgroundColor("#FF6633")
          .alignRules({
            left: {anchor: "row8", align: HorizontalAlign.End}, // 左对齐row8的右侧
            right: {anchor: "__container__", align : HorizontalAlign.End}, // 右对齐容器的右侧
            top: {anchor: "row7", align: VerticalAlign.Top} // 顶部对齐row7的顶部
          })
          .id("row9")
      }
      .width(300).height(300) // 设置RelativeContainer的宽度和高度
      .margin({left: 50}) // 设置左侧外边距
      .border({width:2, color: "#6699FF"}) // 设置边框
    }
    .height('100%') // 设置Row的高度为100%
  }
}

