@Component
struct SearchExample {
  @State Text: string = '' // 用于存储搜索输入框的文本内容
  @State enterTypes: Array<EnterKeyType> = [EnterKeyType.Go, EnterKeyType.Search, EnterKeyType.Send, EnterKeyType.Done, EnterKeyType.Next, EnterKeyType.PREVIOUS, EnterKeyType.NEW_LINE] // 存储多种EnterKeyType类型
  @State index: number = 0 // 用于记录当前使用的EnterKeyType类型的索引

  build() {
    Column({ space: 20 }) { // 使用Column布局，垂直方向上排列子组件，子组件间距为20vp
      Search({ placeholder: '请输入文本', value: this.Text }) // 创建一个搜索输入框，占位符为“请输入文本”，值绑定到@State变量Text
        .width(380) // 设置搜索输入框的宽度为380vp
        .enterKeyType(this.enterTypes[this.index]) // 根据@State变量index动态设置输入框的enterKeyType属性
        .onChange((value: string) => { // 监听输入框文本变化事件
          this.Text = value // 更新@State变量Text的值
        })
        .onSubmit((value: String) => { // 监听输入框提交事件
          console.log("trigger search onsubmit" + value); // 打印提交的文本内容
        })

      Button('改变EnterKeyType').onClick(() => { // 创建一个按钮，文本为“改变EnterKeyType”，点击事件处理函数
        this.index = (this.index + 1) % this.enterTypes.length; // 更新@State变量index的值，循环使用enterTypes数组中的EnterKeyType类型
      })
    }.width('100%') // 设置Column布局的宽度为100%
  }
