示例：该组件通过 Column 布局实现了一个包含搜索框的界面。布局宽度占据整个屏幕的 90%，高度自适应内容，内边距为左右 5%。组件的垂直方向上包含一个 Search 组件，该组件的宽度为 95%，顶部外边距为 100vp。
Search 组件的样式包括宽度、边距等属性，支持自定义菜单扩展项。Search 组件的功能包括文本输入和自定义菜单项的点击事件，用户可以通过点击菜单项触发相应操作，菜单项也可以在点击时进行拦截或不拦截。
整个布局通过 Column 布局保证 Search 组件在垂直方向上有序排列，确保界面整洁美观。
@Entry
@Component
struct Index {
  @State text: string = 'Search editMenuOptions' // 定义一个状态变量 text，初始值为 'Search editMenuOptions'

  // 定义 onCreateMenu 方法，用于自定义菜单项的内容、图标和回调方法
  onCreateMenu(menuItems: Array<TextMenuItem>) {
    menuItems.forEach((value, index) => {
      value.icon = $r('app.media.startIcon') // 为每个菜单项设置图标，图标资源名为 'app.media.startIcon'
      if (value.id.equals(TextMenuItemId.COPY)) {
        value.content = "复制change" // 如果菜单项的 id 为 COPY，则修改其内容为 "复制change"
      }
      if (value.id.equals(TextMenuItemId.SELECT_ALL)) {
        value.content = "全选change" // 如果菜单项的 id 为 SELECT_ALL，则修改其内容为 "全选change"
      }
    })
    let item1: TextMenuItem = {
      content: 'custom1', // 定义一个自定义菜单项，内容为 'custom1'
      icon: $r('app.media.startIcon'), // 设置图标，图标资源名为 'app.media.startIcon'
      id: TextMenuItemId.of('custom1'), // 设置菜单项的 id 为 'custom1'
    }
    let item2: TextMenuItem = {
      content: 'custom2', // 定义一个自定义菜单项，内容为 'custom2'
      id: TextMenuItemId.of('custom2'), // 设置菜单项的 id 为 'custom2'
      icon: $r('app.media.startIcon'), // 设置图标，图标资源名为 'app.media.startIcon'
    }
    menuItems.push(item1) // 将自定义菜单项 item1 添加到菜单项列表的末尾
    menuItems.unshift(item2) // 将自定义菜单项 item2 添加到菜单项列表的开头
    return menuItems // 返回修改后的菜单项列表
  }

  build() {
    Column() {
      Search({ value: this.text }) // 创建一个 Search 组件，绑定状态变量 text
        .width('95%') // 设置 Search 组件的宽度为 95%
        .editMenuOptions({
          onCreateMenu: this.onCreateMenu, // 设置 onCreateMenu 回调方法，用于自定义菜单项
          onMenuItemClick: (menuItem: TextMenuItem, textRange: TextRange) => { // 设置 onMenuItemClick 回调方法，用于处理菜单项点击事件
            if (menuItem.id.equals(TextMenuItemId.of("custom2"))) {
              console.log("拦截 id: custom2 start:" + textRange.start + "; end:" + textRange.end) // 如果点击的菜单项 id 为 'custom2'，则拦截并输出日志
              return true; // 返回 true 表示拦截该点击事件
            }
            if (menuItem.id.equals(TextMenuItemId.COPY)) {
              console.log("拦截 COPY start:" + textRange.start + "; end:" + textRange.end) // 如果点击的菜单项 id 为 COPY，则拦截并输出日志
              return true; // 返回 true 表示拦截该点击事件
            }
            if (menuItem.id.equals(TextMenuItemId.SELECT_ALL)) {
              console.log("不拦截 SELECT_ALL start:" + textRange.start + "; end:" + textRange.end) // 如果点击的菜单项 id 为 SELECT_ALL，则不拦截并输出日志
              return false; // 返回 false 表示不拦截该点击事件
            }
            return false; // 默认返回 false，表示不拦截其他菜单项的点击事件
          }
        })
        .margin({ top: 100 }) // 设置 Search 组件的顶部外边距为 100vp
    }
    .width("90%") // 设置 Column 组件的宽度为 90%
    .margin("5%") // 设置 Column 组件的左右外边距为 5%
  }
}

示例：该组件实现了一个搜索框界面，通过Column布局将搜索框垂直居中显示在屏幕中央。搜索框的宽度为屏幕宽度的95%，高度为40vp，背景颜色为浅灰色（#F5F5F5），边距为10vp。搜索框的占位符文本颜色为灰色，字体大小为14，字重为400。输入文本的字体大小和字重与占位符文本一致。

搜索框的左侧显示一个红色的搜索图标，图标使用系统资源'sys.symbol.magnifyingglass'。搜索框的右侧显示一个绿色的取消按钮，按钮样式为常驻显示（CancelButtonStyle.CONSTANT），图标使用系统资源'sys.symbol.xmark'。搜索框底部显示一个文本为'SEARCH'的搜索按钮。

组件的功能包括用户输入搜索内容、点击取消按钮清空输入内容、点击搜索按钮提交搜索内容。
@Entry
@Component
struct SearchExample {
  // 创建一个SearchController实例，用于控制搜索框的行为
  controller: SearchController = new SearchController()

  // 定义一个状态变量changeValue，用于存储用户输入的搜索内容
  @State changeValue: string = ''

  // 定义一个状态变量submitValue，用于存储提交的搜索内容
  @State submitValue: string = ''

  build() {
    Column() {
      // 创建一个Search组件，绑定changeValue作为输入值，占位符文本为'Type to search...'，使用controller控制搜索框
      Search({ value: this.changeValue, placeholder: 'Type to search...', controller: this.controller })
        // 设置搜索框左侧的搜索图标，使用SymbolGlyphModifier设置图标样式，图标颜色为红色
        .searchIcon(new SymbolGlyphModifier($r('sys.symbol.magnifyingglass')).fontColor([Color.Red]))
        // 设置搜索框右侧的取消按钮，按钮样式为常驻显示，图标颜色为绿色
        .cancelButton({
          style: CancelButtonStyle.CONSTANT,
          icon: new SymbolGlyphModifier($r('sys.symbol.xmark')).fontColor([Color.Green])
        })
        // 设置搜索框底部的搜索按钮文本为'SEARCH'
        .searchButton('SEARCH')
        // 设置搜索框的宽度为屏幕宽度的95%
        .width('95%')
        // 设置搜索框的高度为40vp
        .height(40)
        // 设置搜索框的背景颜色为浅灰色（#F5F5F5）
        .backgroundColor('#F5F5F5')
        // 设置搜索框占位符文本的颜色为灰色
        .placeholderColor(Color.Grey)
        // 设置搜索框占位符文本的字体大小为14，字重为400
        .placeholderFont({ size: 14, weight: 400 })
        // 设置搜索框输入文本的字体大小为14，字重为400
        .textFont({ size: 14, weight: 400 })
        // 设置搜索框的边距为10vp
        .margin(10)
    }
    // 设置Column的宽度为屏幕宽度
    .width('100%')
    // 设置Column的高度为屏幕高度
    .height('100%')
  }
}

示例：该组件通过Column布局实现了一个搜索输入框和按钮的界面。布局宽度占据整个屏幕，高度根据内容自适应。组件的垂直方向上被分为两个部分：一个搜索输入框和一个按钮。搜索输入框的宽度为380vp，按钮的宽度为100%。
搜索输入框的样式包括占位符文本“请输入文本”，输入框的值绑定到@State变量Text，输入框的enterKeyType属性根据@State变量index动态设置，支持多种EnterKeyType类型。输入框的功能包括输入文本的实时更新和提交事件的触发。
按钮的样式包括文本“改变EnterKeyType”，按钮的功能是点击后改变输入框的enterKeyType属性。
整个布局通过Column布局保证搜索输入框和按钮在垂直方向上有序排列，确保界面整洁美观。
@Entry
@Component
struct SearchExample {
  @State Text: string = '' // 用于存储搜索输入框的文本内容
  @State enterTypes: Array<EnterKeyType> = [EnterKeyType.Go, EnterKeyType.Search, EnterKeyType.Send, EnterKeyType.Done, EnterKeyType.Next, EnterKeyType.PREVIOUS, EnterKeyType.NEW_LINE] // 存储多种EnterKeyType类型
  @State index: number = 0 // 用于记录当前使用的EnterKeyType类型的索引

  build() {
    Column({ space: 20 }) { // 使用Column布局，垂直方向上排列子组件，子组件间距为20vp
      Search({ placeholder: '请输入文本', value: this.Text }) // 创建一个搜索输入框，占位符为“请输入文本”，值绑定到@State变量Text
        .width(380) // 设置搜索输入框的宽度为380vp
        .enterKeyType(this.enterTypes[this.index]) // 根据@State变量index动态设置输入框的enterKeyType属性
        .onChange((value: string) => { // 监听输入框文本变化事件
          this.Text = value // 更新@State变量Text的值
        })
        .onSubmit((value: String) => { // 监听输入框提交事件
          console.log("trigger search onsubmit" + value); // 打印提交的文本内容
        })

      Button('改变EnterKeyType').onClick(() => { // 创建一个按钮，文本为“改变EnterKeyType”，点击事件处理函数
        this.index = (this.index + 1) % this.enterTypes.length; // 更新@State变量index的值，循环使用enterTypes数组中的EnterKeyType类型
      })
    }.width('100%') // 设置Column布局的宽度为100%
  }
}

