@Component
struct TextExample11 {
  @State text: string = 'Text editMenuOptions' // 定义文本内容的状态变量

  // 创建自定义菜单项的方法
  onCreateMenu(menuItems: Array<TextMenuItem>) {
    menuItems.forEach((value, index) => {
      value.icon = $r('app.media.startIcon') // 设置菜单项的图标
      if (value.id.equals(TextMenuItemId.COPY)) {
        value.content = "复制change" // 修改复制菜单项的文本内容
      }
      if (value.id.equals(TextMenuItemId.SELECT_ALL)) {
        value.content = "全选change" // 修改全选菜单项的文本内容
      }
    })
    let item1: TextMenuItem = {
      content: 'custom1', // 自定义菜单项1的文本内容
      icon: $r('app.media.startIcon'), // 自定义菜单项1的图标
      id: TextMenuItemId.of('custom1'), // 自定义菜单项1的ID
    }
    let item2: TextMenuItem = {
      content: 'custom2', // 自定义菜单项2的文本内容
      id: TextMenuItemId.of('custom2'), // 自定义菜单项2的ID
      icon: $r('app.media.startIcon'), // 自定义菜单项2的图标
    }
    menuItems.push(item1) // 将自定义菜单项1添加到菜单项数组的末尾
    menuItems.unshift(item2) // 将自定义菜单项2添加到菜单项数组的开头
    return menuItems // 返回修改后的菜单项数组
  }

  build() {
    Column() {
      Text(this.text) // 显示文本内容
        .fontSize(20) // 设置字体大小为20vp
        .copyOption(CopyOptions.LocalDevice) // 设置支持本地设备的复制操作
        .editMenuOptions({
          onCreateMenu: this.onCreateMenu, // 设置创建自定义菜单项的方法
          onMenuItemClick: (menuItem: TextMenuItem, textRange: TextRange) => { // 设置菜单项点击的回调方法
            if (menuItem.id.equals(TextMenuItemId.of("custom2"))) {
              console.log("拦截 id: custom2 start:" + textRange.start + "; end:" + textRange.end) // 拦截自定义菜单项2的点击事件
              return true;
            }
            if (menuItem.id.equals(TextMenuItemId.COPY)) {
              console.log("拦截 COPY start:" + textRange.start + "; end:" + textRange.end) // 拦截复制菜单项的点击事件
              return true;
            }
            if (menuItem.id.equals(TextMenuItemId.SELECT_ALL)) {
              console.log("不拦截 SELECT_ALL start:" + textRange.start + "; end:" + textRange.end) // 不拦截全选菜单项的点击事件
              return false;
            }
            return false;
          }
        })
        .margin({ top: 100 }) // 设置文本组件的顶部边距为100vp
    }
    .width("90%") // 设置布局宽度为屏幕的90%
    .margin("5%") // 设置布局的内边距为左右5%
  }
}

