          }
        }.width('50%').height(300)
      }
    }.width('100%') // 主布局宽度为100%
  }
}

示例：该组件通过 Column 布局实现了一个展示多种 Slider 组件样式和功能的界面。布局宽度占据整个屏幕，高度根据内容自适应。组件的垂直方向上被分为多个部分，每个部分包含一个标题和一个 Slider 组件。每个 Slider 组件的样式和功能各不相同，展示了不同的属性设置和交互效果。

布局属性：
- 使用 Column 布局，垂直排列各个子组件。
- 每个子组件的宽度设置为 '90%'，确保在不同屏幕尺寸下都能良好显示。
- 使用 space 属性设置子组件之间的间距为 8vp。
- 使用 margin 属性设置标题的上下边距为 15vp。

组件的样式和外观：
- 标题使用 Text 组件，字体大小为 9vp，颜色为 0xCCCCCC，居中显示。
- Slider 组件的样式包括 OutSet 和 InSet 两种，分别展示了不同的外观效果。
- 通过 blockSize、blockBorderColor、blockBorderWidth 等属性自定义滑块的尺寸、边框颜色和宽度。
- 通过 stepSize、stepColor 等属性自定义步长和步长颜色。
- 通过 trackBorderRadius、selectedBorderRadius 等属性自定义轨道和选中部分的圆角。
- 通过 blockStyle 属性自定义滑块的样式，包括默认样式、图片样式和自定义形状样式。
- 通过 showTips 属性在滑块上显示提示信息，提示信息的内容为当前滑块的值。

组件的排列和嵌套关系：
- 使用 Column 布局，垂直排列各个子组件。
- 每个子组件包含一个标题和一个 Slider 组件，标题在 Slider 组件的上方。
- 使用 Divider 组件分隔不同的 Slider 组件部分，确保界面整洁。

组件的功能和交互：
- Slider 组件支持用户通过拖动滑块改变值，并实时更新显示的提示信息。
- 通过 onChange 事件监听滑块值的变化，并将变化后的值更新到状态变量 tipsValue 中。
- 通过 showTips 属性在滑块上显示提示信息，提示信息的内容为当前滑块的值。
@Entry
@Component
struct SliderExample {
  @State tipsValue: number = 40 // 初始化状态变量 tipsValue，用于存储滑块的当前值

  build() {
    Column({ space: 8 }) { // 使用 Column 布局，设置子组件之间的间距为 8vp
      Text('block').fontSize(9).fontColor(0xCCCCCC).margin(15).width('90%') // 标题文本，字体大小为 9vp，颜色为 0xCCCCCC，上下边距为 15vp，宽度为 '90%'
      Slider({ style: SliderStyle.OutSet, value: 40 }) // 创建一个 Slider 组件，样式为 OutSet，初始值为 40
        .blockSize({ width: 40, height: 40 }) // 设置滑块的尺寸为 40x40vp
        .blockBorderColor(Color.Red) // 设置滑块边框颜色为红色
        .blockBorderWidth(5) // 设置滑块边框宽度为 5vp
      Divider() // 分隔线，用于分隔不同的 Slider 组件部分
      Text('step').fontSize(9).fontColor(0xCCCCCC).margin(15).width('90%') // 标题文本，字体大小为 9vp，颜色为 0xCCCCCC，上下边距为 15vp，宽度为 '90%'
      Slider({ style: SliderStyle.InSet, value: 40, step: 10 }) // 创建一个 Slider 组件，样式为 InSet，初始值为 40，步长为 10
        .showSteps(true) // 显示步长标记
        .stepSize(8) // 设置步长标记的尺寸为 8vp
        .stepColor(Color.Yellow) // 设置步长标记的颜色为黄色
      Divider() // 分隔线，用于分隔不同的 Slider 组件部分
      Text('track').fontSize(9).fontColor(0xCCCCCC).margin(15).width('90%') // 标题文本，字体大小为 9vp，颜色为 0xCCCCCC，上下边距为 15vp，宽度为 '90%'
      Slider({ style: SliderStyle.InSet, value: 40 }) // 创建一个 Slider 组件，样式为 InSet，初始值为 40
        .trackBorderRadius(2) // 设置轨道部分的圆角为 2vp
      Divider() // 分隔线，用于分隔不同的 Slider 组件部分
      Text('selected').fontSize(9).fontColor(0xCCCCCC).margin(15).width('90%') // 标题文本，字体大小为 9vp，颜色为 0xCCCCCC，上下边距为 15vp，宽度为 '90%'
      Slider({ style: SliderStyle.InSet, value: 40 }) // 创建一个 Slider 组件，样式为 InSet，初始值为 40
        .selectedBorderRadius(2) // 设置选中部分的圆角为 2vp
      Divider() // 分隔线，用于分隔不同的 Slider 组件部分
      Text('blockStyle').fontSize(9).fontColor(0xCCCCCC).margin(15).width('90%') // 标题文本，字体大小为 9vp，颜色为 0xCCCCCC，上下边距为 15vp，宽度为 '90%'
      Slider({ style: SliderStyle.OutSet, value: 40 }) // 创建一个 Slider 组件，样式为 OutSet，初始值为 40
        .blockStyle({ type: SliderBlockType.DEFAULT }) // 设置滑块样式为默认样式
      Slider({ style: SliderStyle.OutSet, value: 40 }) // 创建一个 Slider 组件，样式为 OutSet，初始值为 40
        .blockStyle({ type: SliderBlockType.IMAGE, image: $r('sys.media.ohos_app_icon') }) // 设置滑块样式为图片样式，图片资源为系统应用图标
      Slider({ style: SliderStyle.OutSet, value: 40 }) // 创建一个 Slider 组件，样式为 OutSet，初始值为 40
        .blockSize({ width: '60px', height: '60px' }) // 设置滑块的尺寸为 60x60vp
        .blockColor(Color.Red) // 设置滑块颜色为红色
        .blockStyle({ type: SliderBlockType.SHAPE, shape: new Path({ commands: 'M60 60 M30 30 L15 56 L45 56 Z' }) }) // 设置滑块样式为自定义形状样式，形状为自定义路径
      Divider() // 分隔线，用于分隔不同的 Slider 组件部分
      Text('tips').fontSize(9).fontColor(0xCCCCCC).margin(15).width('90%') // 标题文本，字体大小为 9vp，颜色为 0xCCCCCC，上下边距为 15vp，宽度为 '90%'
      Slider({ style: SliderStyle.InSet, value: this.tipsValue }) // 创建一个 Slider 组件，样式为 InSet，初始值为状态变量 tipsValue
        .showTips(true, this.tipsValue.toFixed()) // 显示提示信息，提示信息内容为当前滑块值
        .onChange(value => { // 监听滑块值的变化事件
          this.tipsValue = value // 更新状态变量 tipsValue 为当前滑块值
        })
    }
  }
}

