示例：该组件展示了一个文本组件（Text）及其相关信息的界面。布局宽度占据整个屏幕，高度根据内容自适应。组件的垂直方向上被分为多个部分，每个部分包含一个标题和一组文本或按钮。每个部分的文本以垂直布局方式排列，文本之间的间距均匀分布，且对齐方式为居中对齐。

文本组件的样式包括字体大小、颜色、边框宽度等属性，支持不同的样式展示。按钮的功能包括点击事件和状态效果，用户可以通过点击按钮触发相应操作，按钮也可以在启用或禁用状态下进行展示。

整个布局通过 Column 布局保证文本和按钮在垂直方向上有序排列，确保界面整洁美观。
@Entry
@Component
struct TextExample9 {
  // 定义状态变量，用于存储文本组件的行数、字形位置信息和行度量信息
  @State lineCount: string = ""
  @State glyphPositionAtCoordinate: string = ""
  @State lineMetrics: string = ""

  // 创建一个 TextController 实例，用于控制文本组件
  controller: TextController = new TextController()

  // 定义文本内容
  @State textStr: string = 'Hello World! 您好，世界！'

  build() {
    Scroll() {
      Column() {
        // 显示标题文本，字体大小为9，颜色为浅灰色，宽度为90%，内边距为10
        Text('Text组件getLayoutManager接口获取段落相对组件的信息')
          .fontSize(9)
          .fontColor(0xCCCCCC)
          .width('90%')
          .padding(10)

        // 显示文本内容，字体大小为25，边框宽度为1，当文本区域发生变化时获取行数
        Text(this.textStr, { controller: this.controller })
          .fontSize(25)
          .borderWidth(1)
          .onAreaChange(() => {
            let layoutManager: LayoutManager = this.controller.getLayoutManager()
            this.lineCount = "LineCount: " + layoutManager.getLineCount()
          })

        // 显示行数标题，字体大小为9，颜色为浅灰色，宽度为90%，内边距为10
        Text('LineCount').fontSize(9).fontColor(0xCCCCCC).width('90%').padding(10)

        // 显示行数信息
        Text(this.lineCount)

        // 显示字形位置标题，字体大小为9，颜色为浅灰色，宽度为90%，内边距为10
        Text('GlyphPositionAtCoordinate').fontSize(9).fontColor(0xCCCCCC).width('90%').padding(10)

        // 显示按钮，点击按钮时获取相对组件坐标[150,50]的字形信息
        Button("相对组件坐标[150,50]字形信息")
          .onClick(() => {
            let layoutManager: LayoutManager = this.controller.getLayoutManager()
            let position: PositionWithAffinity = layoutManager.getGlyphPositionAtCoordinate(150, 50)
            this.glyphPositionAtCoordinate =
              "相对组件坐标[150,50] glyphPositionAtCoordinate position: " + position.position + " affinity: " +
              position.affinity
          })
          .margin({ bottom: 20, top: 10 })

        // 显示字形位置信息
        Text(this.glyphPositionAtCoordinate)

        // 显示行度量标题，字体大小为9，颜色为浅灰色，宽度为90%，内边距为10
        Text('LineMetrics').fontSize(9).fontColor(0xCCCCCC).width('90%').padding(10)

        // 显示按钮，点击按钮时获取首行行信息、文本样式信息、以及字体属性信息
        Button("首行行信息、文本样式信息、以及字体属性信息")
          .onClick(() => {
            let layoutManager: LayoutManager = this.controller.getLayoutManager()
            let lineMetrics: LineMetrics = layoutManager.getLineMetrics(0)
            this.lineMetrics = "lineMetrics is " + JSON.stringify(lineMetrics) + '\\n\\n'
            let runMetrics = lineMetrics.runMetrics
            runMetrics.forEach((value, key) => {
              this.lineMetrics += "runMetrics key is " + key + " " + JSON.stringify(value) + "\\n\\n"
            });
          })
          .margin({ bottom: 20, top: 10 })

        // 显示行度量信息
        Text(this.lineMetrics)
      }
      .margin({ top: 100, left: 8, right: 8 })
    }
  }
}

示例：该组件通过Column布局实现了一个展示文本处理效果的界面。布局宽度占据整个屏幕，高度根据内容自适应。组件的垂直方向上被分为多个部分，每个部分包含一个文本展示区域和一组按钮。每个文本展示区域的文本以不同的省略号模式和断词模式进行展示，按钮用于切换这些模式。

文本展示区域的样式包括字体大小、边框、行高、最大行数、宽度等属性，支持不同的样式展示。按钮的样式包括背景颜色、边框圆角（或半径）、宽度和高度等属性，支持不同的样式展示。按钮组之间通过Row组件进行分隔。

按钮的功能包括点击事件和状态效果，用户可以通过点击按钮触发相应操作，按钮也可以在启用或禁用状态下进行展示。整个布局通过Column布局保证文本展示区域和按钮在垂直方向上有序排列，确保界面整洁美观。
@Entry
@Component
struct TextExample4 {
  @State text: string =
    'The text component is used to display a piece of textual information.Support universal attributes and universal text attributes.'
  @State ellipsisModeIndex: number = 0;
  @State ellipsisMode: EllipsisMode[] = [EllipsisMode.START, EllipsisMode.CENTER, EllipsisMode.END]
  @State ellipsisModeStr: string[] = ['START', 'CENTER', 'END']
  @State wordBreakIndex: number = 0;
  @State wordBreak: WordBreak[] = [WordBreak.NORMAL, WordBreak.BREAK_ALL, WordBreak.BREAK_WORD]
  @State wordBreakStr: string[] = ['NORMAL', 'BREAK_ALL', 'BREAK_WORD']
  @State textClip: boolean = false

  build() {
    Column({ space: 10 }) {
      // 第一个文本展示区域，展示省略号模式的效果
      Text(this.text)
        .fontSize(16) // 设置字体大小为16
        .border({ width: 1 }) // 设置边框宽度为1
        .lineHeight(20) // 设置行高为20
        .maxLines(1) // 设置最大行数为1
        .textOverflow({ overflow: TextOverflow.Ellipsis }) // 设置文本溢出时显示省略号
        .ellipsisMode(this.ellipsisMode[this.ellipsisModeIndex]) // 设置省略号模式
        .width(300) // 设置宽度为300
        .margin({ left: 20, top: 20 }) // 设置左边距和上边距为20

      // 按钮区域，用于切换省略号模式
      Row() {
        Button('更改省略号位置：' + this.ellipsisModeStr[this.ellipsisModeIndex]).onClick(() => {
          this.ellipsisModeIndex++
          if (this.ellipsisModeIndex > (this.ellipsisModeStr.length - 1)) {
            this.ellipsisModeIndex = 0
          }
        })
      }

      // 第二个文本展示区域，展示断词模式的效果
      Text('This is set wordBreak to WordBreak text Taumatawhakatangihangakoauauotamateaturipukakapikimaungahoronukupokaiwhenuakitanatahu.')
        .fontSize(12) // 设置字体大小为12
        .border({ width: 1 }) // 设置边框宽度为1
        .wordBreak(WordBreak.NORMAL) // 设置断词模式为NORMAL
        .lineHeight(20) // 设置行高为20
        .maxLines(2) // 设置最大行数为2
        .clip(this.textClip) // 设置是否裁剪文本
        .width(260) // 设置宽度为260

      // 按钮区域，用于切换裁剪模式
      Row() {
        Button('切换clip：' + this.textClip).onClick(() => {
          this.textClip = !this.textClip
        })
      }

      // 第三个文本展示区域，展示断词模式的效果
      Text(this.text)
        .fontSize(12) // 设置字体大小为12
        .border({ width: 1 }) // 设置边框宽度为1
        .maxLines(2) // 设置最大行数为2
        .textOverflow({ overflow: TextOverflow.Ellipsis }) // 设置文本溢出时显示省略号
        .wordBreak(this.wordBreak[this.wordBreakIndex]) // 设置断词模式
        .lineHeight(20) // 设置行高为20
        .width(260) // 设置宽度为260

      // 按钮区域，用于切换断词模式
      Row() {
        Button('更改wordBreak模式：' + this.wordBreakStr[this.wordBreakIndex]).onClick(() => {
          this.wordBreakIndex++
          if (this.wordBreakIndex > (this.wordBreakStr.length - 1)) {
            this.wordBreakIndex = 0
          }
        })
      }
    }
  }
}

