        } else if (this.alignListItem == ListItemAlign.Center) {
          this.alignListItem = ListItemAlign.End // 如果当前对齐方式为 Center，则切换为 End
        } else {
          this.alignListItem = ListItemAlign.Start // 如果当前对齐方式为 End，则切换为 Start
        }
      })
    }
    .width('100%') // 设置 Column 宽度为 100%
