示例：该组件通过 Flex 布局实现了一个展示文本对齐方式、文本溢出处理和行高的界面。布局宽度为 340vp，高度为 600vp，内边距为左右 35vp、顶部 35vp。组件的垂直方向上被分为多个部分，每个部分包含一个标题和一组文本。每个文本组的文本以不同的对齐方式排列，且对齐方式为居中对齐。
文本的样式包括字体大小、边框、内边距、宽度和高度等属性，支持不同的样式展示。文本组之间通过 Flex 组件进行分隔。文本的功能包括文本对齐、文本溢出处理和行高设置，用户可以通过设置不同的属性来控制文本的展示效果。
整个布局通过 Flex 布局保证文本在垂直方向上有序排列，确保界面整洁美观。
@Extend(Text)
function style(TextAlign: TextAlign) {
  .textAlign(TextAlign) // 设置文本对齐方式
  .fontSize(12) // 设置字体大小为 12
  .border({ width: 1 }) // 设置边框宽度为 1
  .padding(10) // 设置内边距为 10
  .width('100%') // 设置宽度为 100%
}

@Entry
@Component
struct TextExample1 {
  build() {
    Flex({ direction: FlexDirection.Column, alignItems: ItemAlign.Start, justifyContent: FlexAlign.SpaceBetween }) {

      Text('textAlign').fontSize(9).fontColor(0xCCCCCC) // 设置标题文本，字体大小为 9，颜色为 0xCCCCCC
      Text('TextAlign set to Center.')
        .style(TextAlign.Center) // 设置文本对齐方式为居中
      Text('TextAlign set to Start.')
        .style(TextAlign.Start) // 设置文本对齐方式为开始
      Text('TextAlign set to End.')
        .style(TextAlign.End) // 设置文本对齐方式为结束

      Text('This is the text content with textAlign set to Center.')
        .style(TextAlign.Center) // 设置文本对齐方式为居中
      Text('This is the text content with textAlign set to Start.')
        .style(TextAlign.Start) // 设置文本对齐方式为开始
      Text('This is the text content with textAlign set to End.')
        .style(TextAlign.End) // 设置文本对齐方式为结束

      Text('TextOverflow+maxLines').fontSize(9).fontColor(0xCCCCCC) // 设置标题文本，字体大小为 9，颜色为 0xCCCCCC

      Text('This is the setting of textOverflow to Clip text content This is the setting of textOverflow to None text content. This is the setting of textOverflow to Clip text content This is the setting of textOverflow to None text content.')
        .textOverflow({ overflow: TextOverflow.Clip }) // 设置文本溢出处理方式为剪切
        .maxLines(1) // 设置最大行数为 1
        .style(TextAlign.Start) // 设置文本对齐方式为开始

      Text('This is set textOverflow to Ellipsis text content This is set textOverflow to Ellipsis text content.')
        .textOverflow({ overflow: TextOverflow.Ellipsis }) // 设置文本溢出处理方式为省略号
        .maxLines(1) // 设置最大行数为 1
        .style(TextAlign.Start) // 设置文本对齐方式为开始

      Text('lineHeight').fontSize(9).fontColor(0xCCCCCC) // 设置标题文本，字体大小为 9，颜色为 0xCCCCCC
      Text('This is the text with the line height set. This is the text with the line height set.')
        .style(TextAlign.Start) // 设置文本对齐方式为开始
      Text('This is the text with the line height set. This is the text with the line height set.')
        .style(TextAlign.Start) // 设置文本对齐方式为开始
        .lineHeight(20) // 设置行高为 20
    }.height(600).width(340).padding({ left: 35, right: 35, top: 35 }) // 设置布局高度为 600vp，宽度为 340vp，内边距为左右 35vp、顶部 35vp
  }
}

示例：该组件展示了一个文本组件（Text）及其相关信息的界面。布局宽度占据整个屏幕，高度根据内容自适应。组件的垂直方向上被分为多个部分，每个部分包含一个标题和一组文本或按钮。每个部分的文本以垂直布局方式排列，文本之间的间距均匀分布，且对齐方式为居中对齐。

文本组件的样式包括字体大小、颜色、边框宽度等属性，支持不同的样式展示。按钮的功能包括点击事件和状态效果，用户可以通过点击按钮触发相应操作，按钮也可以在启用或禁用状态下进行展示。

整个布局通过 Column 布局保证文本和按钮在垂直方向上有序排列，确保界面整洁美观。
@Entry
@Component
struct TextExample9 {
  // 定义状态变量，用于存储文本组件的行数、字形位置信息和行度量信息
  @State lineCount: string = ""
  @State glyphPositionAtCoordinate: string = ""
  @State lineMetrics: string = ""

  // 创建一个 TextController 实例，用于控制文本组件
  controller: TextController = new TextController()

  // 定义文本内容
  @State textStr: string = 'Hello World! 您好，世界！'

  build() {
    Scroll() {
      Column() {
        // 显示标题文本，字体大小为9，颜色为浅灰色，宽度为90%，内边距为10
        Text('Text组件getLayoutManager接口获取段落相对组件的信息')
          .fontSize(9)
          .fontColor(0xCCCCCC)
          .width('90%')
          .padding(10)

        // 显示文本内容，字体大小为25，边框宽度为1，当文本区域发生变化时获取行数
        Text(this.textStr, { controller: this.controller })
          .fontSize(25)
          .borderWidth(1)
          .onAreaChange(() => {
            let layoutManager: LayoutManager = this.controller.getLayoutManager()
            this.lineCount = "LineCount: " + layoutManager.getLineCount()
          })

        // 显示行数标题，字体大小为9，颜色为浅灰色，宽度为90%，内边距为10
        Text('LineCount').fontSize(9).fontColor(0xCCCCCC).width('90%').padding(10)

        // 显示行数信息
        Text(this.lineCount)

        // 显示字形位置标题，字体大小为9，颜色为浅灰色，宽度为90%，内边距为10
        Text('GlyphPositionAtCoordinate').fontSize(9).fontColor(0xCCCCCC).width('90%').padding(10)

        // 显示按钮，点击按钮时获取相对组件坐标[150,50]的字形信息
        Button("相对组件坐标[150,50]字形信息")
          .onClick(() => {
            let layoutManager: LayoutManager = this.controller.getLayoutManager()
            let position: PositionWithAffinity = layoutManager.getGlyphPositionAtCoordinate(150, 50)
            this.glyphPositionAtCoordinate =
              "相对组件坐标[150,50] glyphPositionAtCoordinate position: " + position.position + " affinity: " +
              position.affinity
          })
          .margin({ bottom: 20, top: 10 })

        // 显示字形位置信息
        Text(this.glyphPositionAtCoordinate)

        // 显示行度量标题，字体大小为9，颜色为浅灰色，宽度为90%，内边距为10
        Text('LineMetrics').fontSize(9).fontColor(0xCCCCCC).width('90%').padding(10)

        // 显示按钮，点击按钮时获取首行行信息、文本样式信息、以及字体属性信息
        Button("首行行信息、文本样式信息、以及字体属性信息")
          .onClick(() => {
            let layoutManager: LayoutManager = this.controller.getLayoutManager()
            let lineMetrics: LineMetrics = layoutManager.getLineMetrics(0)
            this.lineMetrics = "lineMetrics is " + JSON.stringify(lineMetrics) + '\\n\\n'
            let runMetrics = lineMetrics.runMetrics
            runMetrics.forEach((value, key) => {
              this.lineMetrics += "runMetrics key is " + key + " " + JSON.stringify(value) + "\\n\\n"
            });
          })
          .margin({ bottom: 20, top: 10 })

        // 显示行度量信息
        Text(this.lineMetrics)
      }
      .margin({ top: 100, left: 8, right: 8 })
    }
  }
}

示例：该组件通过 Flex 布局实现了一个展示文本选择和复制功能的界面。布局宽度为 335vp，高度为 600vp，内边距为左右 35vp、顶部 35vp。组件的垂直方向上被分为多个部分，包括一个文本展示区域、一个按钮和一个显示复制内容的文本区域。

文本展示区域的文本内容为 "This is set selection to Selection text content This is set selection to Selection text content."，字体大小为 12vp，行高为 20vp，边框宽度为 1vp，外边距为 30vp。文本内容支持在应用内复制（CopyOptions.InApp），并且可以通过设置起始和结束位置来选择文本。

按钮的文本为 "Set text selection"，外边距为左 20vp。按钮的功能是点击后设置文本选择的起始位置为 10，结束位置为 30。

显示复制内容的文本区域的文本内容为复制的内容，字体大小为 12vp，外边距为 10vp。

整个布局通过 Flex 布局保证文本、按钮和显示复制内容的文本区域在垂直方向上有序排列，确保界面整洁美观。
@Entry
@Component
struct TextExample5 {
  @State onCopy: string = '' // 存储复制的文本内容
  @State text: string = 'This is set selection to Selection text content This is set selection to Selection text content.' // 文本内容
  @State start: number = 0 // 文本选择的起始位置
  @State end: number = 20 // 文本选择的结束位置

  build() {
    Flex({ direction: FlexDirection.Column, alignItems: ItemAlign.Start, justifyContent: FlexAlign.Start }) {
      Text(this.text)
        .fontSize(12) // 设置字体大小为 12vp
        .border({ width: 1 }) // 设置边框宽度为 1vp
        .lineHeight(20) // 设置行高为 20vp
        .margin(30) // 设置外边距为 30vp
        .copyOption(CopyOptions.InApp) // 设置复制选项为仅在应用内复制
        .selection(this.start, this.end) // 设置文本选择的起始和结束位置
        .onCopy((value: string) => { // 当文本被复制时触发的事件
          this.onCopy = value // 将复制的文本内容存储到 onCopy 变量中
        })
      Button('Set text selection')
        .margin({left:20}) // 设置按钮的外边距为左 20vp
        .onClick(() => { // 按钮点击事件
          this.start = 10 // 设置文本选择的起始位置为 10
          this.end = 30 // 设置文本选择的结束位置为 30
        })
      Text(this.onCopy).fontSize(12).margin(10).key('copy') // 显示复制的文本内容，字体大小为 12vp，外边距为 10vp
    }.height(600).width(335).padding({ left: 35, right: 35, top: 35 }) // 设置布局的高度为 600vp，宽度为 335vp，内边距为左右 35vp、顶部 35vp
  }
}

