示例：该组件实现了一个带有标签页（Tabs）的界面，用户可以通过点击不同的标签页来切换显示不同的内容。布局宽度占据整个屏幕，高度设为 190vp，背景颜色为 #F1F3F5，顶部有 38vp 的边距。标签页的标签栏位于内容区域的底部，高度为 56vp，水平排列，不垂直排列。每个标签页的内容区域包含一个文本和一个分隔线，文本字体大小为 36，颜色为 #182431，字体粗细为 500，透明度为 0.4，上下边距分别为 30vp 和 56.5vp。分隔线的宽度为 0.5vp，颜色为 #182431，透明度为 0.05。

标签页的标签栏部分通过自定义的 `tabBuilder` 方法生成，每个标签包含一个图标和一个文本。图标根据当前选中的标签页显示不同的图标（选中时为 `/common/public_icon_on.svg`，未选中时为 `/common/public_icon_off.svg`），图标的宽度为 24vp，高度为 24vp，底部边距为 4vp，对象适应方式为 `ImageFit.Contain`。文本字体大小为 10，字体粗细为 500，行高为 14，颜色根据是否选中而变化（选中时为 #007DFF，未选中时为 #182431）。

组件的功能包括标签页的切换和选中状态的更新。当用户点击不同的标签页时，`onChange` 事件会触发，更新 `currentIndex` 的值，从而改变标签页的选中状态和内容显示。
@Entry
@Component
struct TabContentExample {
  @State fontColor: string = '#182431' // 未选中标签页的文本颜色
  @State selectedFontColor: string = '#007DFF' // 选中标签页的文本颜色
  @State currentIndex: number = 0 // 当前选中的标签页索引
  private controller: TabsController = new TabsController() // 标签页控制器

  @Builder tabBuilder(index: number) {
    Column() {
      Image(this.currentIndex === index ? '/common/public_icon_on.svg' : '/common/public_icon_off.svg')
        .width(24) // 图标宽度
        .height(24) // 图标高度
        .margin({ bottom: 4 }) // 图标底部边距
        .objectFit(ImageFit.Contain) // 图标适应方式
      Text(`Tab${index + 1}`)
        .fontColor(this.currentIndex === index ? this.selectedFontColor : this.fontColor) // 文本颜色根据选中状态变化
        .fontSize(10) // 文本字体大小
        .fontWeight(500) // 文本字体粗细
        .lineHeight(14) // 文本行高
    }.width('100%') // 标签宽度占据父容器的100%
  }

  build() {
    Column() {
      Tabs({ barPosition: BarPosition.End, controller: this.controller }) {
        TabContent() {
          Column() {
            Text('Tab1')
              .fontSize(36) // 文本字体大小
              .fontColor('#182431') // 文本颜色
              .fontWeight(500) // 文本字体粗细
              .opacity(0.4) // 文本透明度
              .margin({ top: 30, bottom: 56.5 }) // 文本上下边距
            Divider()
              .strokeWidth(0.5) // 分隔线宽度
              .color('#182431') // 分隔线颜色
              .opacity(0.05) // 分隔线透明度
          }.width('100%') // 内容区域宽度占据父容器的100%
        }.tabBar(this.tabBuilder(0)) // 第一个标签页的标签栏

        TabContent() {
          Column() {
            Text('Tab2')
              .fontSize(36) // 文本字体大小
              .fontColor('#182431') // 文本颜色
              .fontWeight(500) // 文本字体粗细
              .opacity(0.4) // 文本透明度
              .margin({ top: 30, bottom: 56.5 }) // 文本上下边距
            Divider()
              .strokeWidth(0.5) // 分隔线宽度
              .color('#182431') // 分隔线颜色
              .opacity(0.05) // 分隔线透明度
          }.width('100%') // 内容区域宽度占据父容器的100%
        }.tabBar(this.tabBuilder(1)) // 第二个标签页的标签栏

        TabContent() {
          Column() {
            Text('Tab3')
              .fontSize(36) // 文本字体大小
              .fontColor('#182431') // 文本颜色
              .fontWeight(500) // 文本字体粗细
              .opacity(0.4) // 文本透明度
              .margin({ top: 30, bottom: 56.5 }) // 文本上下边距
            Divider()
              .strokeWidth(0.5) // 分隔线宽度
              .color('#182431') // 分隔线颜色
              .opacity(0.05) // 分隔线透明度
          }.width('100%') // 内容区域宽度占据父容器的100%
        }.tabBar(this.tabBuilder(2)) // 第三个标签页的标签栏

        TabContent() {
          Column() {
            Text('Tab4')
              .fontSize(36) // 文本字体大小
              .fontColor('#182431') // 文本颜色
              .fontWeight(500) // 文本字体粗细
              .opacity(0.4) // 文本透明度
              .margin({ top: 30, bottom: 56.5 }) // 文本上下边距
            Divider()
              .strokeWidth(0.5) // 分隔线宽度
              .color('#182431') // 分隔线颜色
              .opacity(0.05) // 分隔线透明度
          }.width('100%') // 内容区域宽度占据父容器的100%
        }.tabBar(this.tabBuilder(3)) // 第四个标签页的标签栏
      }
      .vertical(false) // 标签栏水平排列
      .barHeight(56) // 标签栏高度
      .onChange((index: number) => {
        this.currentIndex = index // 更新当前选中的标签页索引
      })
      .width(360) // 标签页宽度
      .height(190) // 标签页高度
      .backgroundColor('#F1F3F5') // 标签页背景颜色
      .margin({ top: 38 }) // 标签页顶部边距
    }.width('100%') // 父容器宽度占据整个屏幕
  }
}

示例：该组件通过 Flex 布局实现了一个带有标签页（Tabs）的界面。布局宽度占据整个屏幕，高度设为 414vp，内边距为顶部 52vp。组件的垂直方向上包含一个 Tabs 组件，Tabs 组件的标签栏位于顶部，标签栏的宽度为 96vp，高度为 414vp，背景颜色为 #F1F3F5。每个标签页的内容通过 TabContent 组件定义，标签页的标签栏内容通过自定义的 tabBuilder 方法生成。

标签栏的内容包括一个图标和一个文本，图标根据当前选中的标签页显示不同的图标（选中时显示 public_icon_on.svg，未选中时显示 public_icon_off.svg），图标的宽度为 24vp，高度为 24vp，对象适应方式为 contain，底部边距为 4vp。文本内容为 "Tab"，字体颜色根据当前选中的标签页显示不同的颜色（选中时为 #007DFF，未选中时为 #182431），字体大小为 10vp，字体粗细为 500，行高为 14vp。

标签页的切换通过 Tabs 组件的 onChange 事件实现，当用户切换标签页时，currentIndex 状态变量会更新为当前选中的标签页索引。整个布局通过 Flex 布局保证标签页在垂直方向上有序排列，确保界面整洁美观。
@Entry
@Component
struct TabContentExample {
  @State fontColor: string = '#182431' // 未选中标签页的字体颜色
  @State selectedFontColor: string = '#007DFF' // 选中标签页的字体颜色
  @State currentIndex: number = 0 // 当前选中的标签页索引
  private controller: TabsController = new TabsController() // Tabs 组件的控制器

  @Builder tabBuilder(index: number) {
    Column() {
      Image(this.currentIndex === index ? '/common/public_icon_on.svg' : '/common/public_icon_off.svg')
        .width(24) // 图标的宽度
        .height(24) // 图标的高度
        .margin({ bottom: 4 }) // 图标的底部边距
        .objectFit(ImageFit.Contain) // 图标的对象适应方式
      Text('Tab')
        .fontColor(this.currentIndex === index ? this.selectedFontColor : this.fontColor) // 根据当前选中的标签页设置字体颜色
        .fontSize(10) // 字体大小
        .fontWeight(500) // 字体粗细
        .lineHeight(14) // 行高
    }.width('100%').height('100%').justifyContent(FlexAlign.Center) // 标签栏内容的布局方式
  }

  build() {
    Column() {
      Tabs({ barPosition: BarPosition.Start, controller: this.controller }) {
        TabContent()
          .tabBar(this.tabBuilder(0)) // 第一个标签页的标签栏内容
        TabContent()
          .tabBar(this.tabBuilder(1)) // 第二个标签页的标签栏内容
        TabContent()
          .tabBar(this.tabBuilder(2)) // 第三个标签页的标签栏内容
        TabContent()
          .tabBar(this.tabBuilder(3)) // 第四个标签页的标签栏内容
      }
      .vertical(true) // 标签栏垂直排列
      .barWidth(96) // 标签栏的宽度
      .barHeight(414) // 标签栏的高度
      .onChange((index: number) => {
        this.currentIndex = index // 更新当前选中的标签页索引
      })
      .width(96) // Tabs 组件的宽度
      .height(414) // Tabs 组件的高度
      .backgroundColor('#F1F3F5') // Tabs 组件的背景颜色
      .margin({ top: 52 }) // Tabs 组件的顶部边距
    }.width('100%') // 整个布局的宽度
  }
}

示例：该组件通过 Tabs 组件实现了一个包含子页签和底部页签的界面。布局宽度占据整个屏幕，高度设为 400vp，内边距为左右 35vp、顶部 35vp。组件的垂直方向上被分为两个主要部分：子页签样式和底部页签样式。

子页签样式部分包含一个 Tabs 组件，其页签位于内容区域的上方（BarPosition.Start）。每个 TabContent 包含一个 Column 组件，背景颜色分别为 Pink、Yellow、Blue 和 Green。每个 TabContent 的页签样式通过 SubTabBarStyle 进行自定义，包括未选中时的文本颜色为红色（Color.Red），选中时的文本颜色为绿色（Color.Green）。

底部页签样式部分同样包含一个 Tabs 组件，其页签位于内容区域的下方（BarPosition.End）。每个 TabContent 包含一个 Column 组件，背景颜色分别为 Pink、Yellow、Blue 和 Green。每个 TabContent 的页签样式通过 BottomTabBarStyle 进行自定义，包括未选中时的文本颜色和图标颜色为红色（Color.Red），选中时的文本颜色和图标颜色为绿色（Color.Green）。

整个布局通过 Column 组件进行垂直排列，确保子页签和底部页签在垂直方向上有序排列，确保界面整洁美观。
@Entry
@Component
struct TabBarStyleExample {
  build() {
    Column({ space: 5 }) {
      Text("子页签样式") // 显示子页签样式的标题
      Column() {
        Tabs({ barPosition: BarPosition.Start }) { // 创建一个 Tabs 组件，页签位于内容区域的上方
          TabContent() {
            Column().width('100%').height('100%').backgroundColor(Color.Pink) // 创建一个 Column 组件，背景颜色为粉色
          }.tabBar(new SubTabBarStyle('Pink') // 设置子页签的样式，标签为 "Pink"
            .labelStyle({ unselectedColor: Color.Red, selectedColor: Color.Green })) // 设置未选中时的文本颜色为红色，选中时的文本颜色为绿色

          TabContent() {
            Column().width('100%').height('100%').backgroundColor(Color.Yellow) // 创建一个 Column 组件，背景颜色为黄色
          }.tabBar(new SubTabBarStyle('Yellow') // 设置子页签的样式，标签为 "Yellow"
            .labelStyle({ unselectedColor: Color.Red, selectedColor: Color.Green })) // 设置未选中时的文本颜色为红色，选中时的文本颜色为绿色

          TabContent() {
            Column().width('100%').height('100%').backgroundColor(Color.Blue) // 创建一个 Column 组件，背景颜色为蓝色
          }.tabBar(new SubTabBarStyle('Blue') // 设置子页签的样式，标签为 "Blue"
            .labelStyle({ unselectedColor: Color.Red, selectedColor: Color.Green })) // 设置未选中时的文本颜色为红色，选中时的文本颜色为绿色

          TabContent() {
            Column().width('100%').height('100%').backgroundColor(Color.Green) // 创建一个 Column 组件，背景颜色为绿色
          }.tabBar(new SubTabBarStyle('Green') // 设置子页签的样式，标签为 "Green"
            .labelStyle({ unselectedColor: Color.Red, selectedColor: Color.Green })) // 设置未选中时的文本颜色为红色，选中时的文本颜色为绿色
        }
        .vertical(false) // 设置 Tabs 组件为水平布局
        .scrollable(true) // 设置 Tabs 组件为可滚动
        .barMode(BarMode.Fixed) // 设置 Tabs 组件的页签模式为固定模式
        .onChange((index: number) => { // 设置 Tabs 组件的切换事件
          console.info(index.toString()) // 打印当前选中的页签索引
        })
        .width('100%') // 设置 Tabs 组件的宽度为 100%
        .backgroundColor(0xF1F3F5) // 设置 Tabs 组件的背景颜色
      }.width('100%').height(200) // 设置 Column 组件的宽度为 100%，高度为 200vp

      Text("底部页签样式") // 显示底部页签样式的标题
      Column() {
        Tabs({ barPosition: BarPosition.End }) { // 创建一个 Tabs 组件，页签位于内容区域的下方
          TabContent() {
            Column().width('100%').height('100%').backgroundColor(Color.Pink) // 创建一个 Column 组件，背景颜色为粉色
          }
          .tabBar(new BottomTabBarStyle('/common/public_icon_off.svg', 'pink') // 设置底部页签的样式，图标路径为 "/common/public_icon_off.svg"，标签为 "pink"
            .labelStyle({ unselectedColor: Color.Red, selectedColor: Color.Green }) // 设置未选中时的文本颜色为红色，选中时的文本颜色为绿色
            .iconStyle({ unselectedColor: Color.Red, selectedColor: Color.Green })) // 设置未选中时的图标颜色为红色，选中时的图标颜色为绿色

          TabContent() {
            Column().width('100%').height('100%').backgroundColor(Color.Yellow) // 创建一个 Column 组件，背景颜色为黄色
          }.tabBar(new BottomTabBarStyle('/common/public_icon_off.svg', 'Yellow') // 设置底部页签的样式，图标路径为 "/common/public_icon_off.svg"，标签为 "Yellow"
            .labelStyle({ unselectedColor: Color.Red, selectedColor: Color.Green }) // 设置未选中时的文本颜色为红色，选中时的文本颜色为绿色
            .iconStyle({ unselectedColor: Color.Red, selectedColor: Color.Green })) // 设置未选中时的图标颜色为红色，选中时的图标颜色为绿色

          TabContent() {
            Column().width('100%').height('100%').backgroundColor(Color.Blue) // 创建一个 Column 组件，背景颜色为蓝色
          }.tabBar(new BottomTabBarStyle('/common/public_icon_off.svg', 'Blue') // 设置底部页签的样式，图标路径为 "/common/public_icon_off.svg"，标签为 "Blue"
            .labelStyle({ unselectedColor: Color.Red, selectedColor: Color.Green }) // 设置未选中时的文本颜色为红色，选中时的文本颜色为绿色
            .iconStyle({ unselectedColor: Color.Red, selectedColor: Color.Green })) // 设置未选中时的图标颜色为红色，选中时的图标颜色为绿色

          TabContent() {
            Column().width('100%').height('100%').backgroundColor(Color.Green) // 创建一个 Column 组件，背景颜色为绿色
          }.tabBar(new BottomTabBarStyle('/common/public_icon_off.svg', 'Green') // 设置底部页签的样式，图标路径为 "/common/public_icon_off.svg"，标签为 "Green"
            .labelStyle({ unselectedColor: Color.Red, selectedColor: Color.Green }) // 设置未选中时的文本颜色为红色，选中时的文本颜色为绿色
            .iconStyle({ unselectedColor: Color.Red, selectedColor: Color.Green })) // 设置未选中时的图标颜色为红色，选中时的图标颜色为绿色
        }
        .vertical(false) // 设置 Tabs 组件为水平布局
        .scrollable(true) // 设置 Tabs 组件为可滚动
        .barMode(BarMode.Fixed) // 设置 Tabs 组件的页签模式为固定模式
        .onChange((index: number) => { // 设置 Tabs 组件的切换事件
          console.info(index.toString()) // 打印当前选中的页签索引
        })
        .width('100%') // 设置 Tabs 组件的宽度为 100%
        .backgroundColor(0xF1F3F5) // 设置 Tabs 组件的背景颜色
      }.width('100%').height(200) // 设置 Column 组件的宽度为 100%，高度为 200vp
    }
  }
}

