      .friction(0.6) // 设置List的摩擦系数
      .lanes({ minLength: (config.contentModifier as MyLoadingProgressStyle).enableLoading?40:80, maxLength: (config.contentModifier as MyLoadingProgressStyle).enableLoading?40:80 }) // 根据enableLoading属性设置List的行长度
      .scrollBar(BarState.Off) // 设置List的滚动条状态为关闭
