接口描述：Text组件的接口定义。
接口参数：{'Text': {"type":["string","Resource"],"required":false,"description":"文本内容。包含子组件Span且未设置属性字符串时不生效，显示Span内容，并且此时text组件的样式不生效。","default":" "}, 'value': {"type":"TextOptions","required":false,"description":"文本组件初始化选项。","default":null}}
设置选中区域。选中区域高亮且显示手柄和文本选择菜单。
属性名称：selection
属性参数：{'selectionStart': {"type":"number","required":true,"description":"所选文本的起始位置。","default":-1}, 'selectionEnd': {"type":"number","required":true,"description":"所选文本的结束位置。","default":-1}}
设置文本装饰线样式及其颜色。
属性名称：decoration
属性参数：{'value': {"type":"DecorationStyleInterface","required":true,"description":"文本装饰线样式对象。默认值：{ type: TextDecorationType.None, color: Color.Black, style: TextDecorationStyle.SOLID } 说明：style参数不支持卡片能力。","default":"{ type: TextDecorationType.None, color: Color.Black, style: TextDecorationStyle.SOLID } "}}
设置字体颜色。
属性名称：fontColor
属性参数：{'value': {"type":"ResourceColor","required":true,"description":"字体颜色。","default":null}}
示例：该组件通过 Column 布局实现了一个展示文本样式的界面。布局宽度占据整个屏幕，内边距为 10vp。组件的垂直方向上被分为三个部分，每个部分包含一个 Text 组件。

第一个 Text 组件用于显示标题 "halfLeading"，字体大小为 9vp，颜色为灰色（0xCCCCCC），外边距为 15vp，宽度占据父容器的 90%。

第二个 Text 组件显示文本 "This is the text with the halfLeading set."，行高为 60vp，启用了 halfLeading 属性，边框宽度为 1vp，宽度占据父容器的 80%。halfLeading 属性用于控制文本的行间距，当设置为 true 时，行间距会减半。

第三个 Text 组件显示文本 "This is the text without the halfLeading set."，行高为 60vp，禁用了 halfLeading 属性，边框宽度为 1vp，宽度占据父容器的 80%。当 halfLeading 属性设置为 false 时，行间距保持默认值。

整个布局通过 Column 布局保证文本在垂直方向上有序排列，确保界面整洁美观。
@Entry
@Component
struct TextExample12 {
  build() {
    Column({ space: 10 }) { // 创建一个垂直布局，子组件之间的间距为 10vp

      Text('halfLeading') // 创建一个 Text 组件，显示标题 "halfLeading"
        .fontSize(9) // 设置字体大小为 9vp
        .fontColor(0xCCCCCC) // 设置字体颜色为灰色（0xCCCCCC）
        .margin(15) // 设置外边距为 15vp
        .width('90%') // 设置宽度为父容器的 90%

      Text("This is the text with the halfLeading set.") // 创建一个 Text 组件，显示文本 "This is the text with the halfLeading set."
        .lineHeight(60) // 设置行高为 60vp
        .halfLeading(true) // 启用 halfLeading 属性，行间距减半
        .borderWidth(1) // 设置边框宽度为 1vp
        .width('80%') // 设置宽度为父容器的 80%

      Text("This is the text without the halfLeading set.") // 创建一个 Text 组件，显示文本 "This is the text without the halfLeading set."
        .lineHeight(60) // 设置行高为 60vp
        .halfLeading(false) // 禁用 halfLeading 属性，行间距保持默认值
        .borderWidth(1) // 设置边框宽度为 1vp
        .width('80%') // 设置宽度为父容器的 80%
    }
  }
}

示例：该组件通过 Column 布局实现了一个展示可选择文本的界面。布局宽度占据整个屏幕，高度根据内容自适应，顶部外边距为 100vp。组件的垂直方向上包含一个 Text 组件，用于展示一段文本。

Text 组件的样式包括宽度为 300vp，高度为 100vp，最大显示行数为 5 行，字体颜色为黑色。文本内容为一段较长的字符串，支持在应用内复制（通过 copyOption 属性设置）。文本的选中范围通过 selection 属性设置为从第 3 个字符到第 8 个字符。

组件的功能包括文本的可选择性，通过 textSelectable 属性设置为 TextSelectableMode.SELECTABLE_FOCUSABLE，使得文本在获得焦点时可以触发键盘框选文本功能。

整个布局通过 Column 布局保证 Text 组件在垂直方向上居中显示，确保界面简洁明了。
@Entry
@Component
struct TextExample10 {
  @State message: string = 'TextTextTextTextTextTextTextText' + 'TextTextTextTextTextTextTextTextTextTextTextTextTextTextTextText';

  build() {
    Column() {
      Text(this.message)
        .width(300) // 设置 Text 组件的宽度为 300vp
        .height(100) // 设置 Text 组件的高度为 100vp
        .maxLines(5) // 设置 Text 组件的最大显示行数为 5 行
        .fontColor(Color.Black) // 设置 Text 组件的字体颜色为黑色
        .copyOption(CopyOptions.InApp) // 设置 Text 组件的复制选项为仅在应用内复制
        .selection(3, 8) // 设置 Text 组件的选中范围为从第 3 个字符到第 8 个字符
        .textSelectable(TextSelectableMode.SELECTABLE_FOCUSABLE) // 设置 Text 组件的可选择模式为 SELECTABLE_FOCUSABLE，使得文本在获得焦点时可以触发键盘框选文本功能
    }.width('100%') // 设置 Column 组件的宽度为 100%
    .margin({ top: 100 }) // 设置 Column 组件的顶部外边距为 100vp
  }
}

示例：该组件通过Column布局实现了一个包含文本和图像的展示界面。布局宽度占据整个屏幕，高度设为100%，内边距为25vp。组件的垂直方向上被分为两个部分，第一个部分包含一个带有边框的文本和图像区域，第二个部分包含一个自定义的菜单区域。
文本和图像区域通过Column布局实现，宽度为200vp，高度为100vp，边框宽度为1vp，颜色为红色。文本和图像区域内的文本和图像通过Span和ImageSpan组件进行展示，文本内容为"Hello World"，图像内容为应用内的图标资源。文本和图像区域支持长按、右键点击和选择操作，分别触发不同的自定义菜单。
自定义菜单区域通过Builder装饰器定义了三个不同的菜单，分别对应长按图像、右键点击文本和选择混合内容的操作。每个菜单包含一个Column布局，内部嵌套一个Menu组件，Menu组件内包含一个MenuItemGroup组件，MenuItemGroup组件内包含三个MenuItem组件。每个MenuItem组件包含一个图标、内容和点击事件，点击事件触发时关闭当前菜单。
整个布局通过Column布局保证文本和图像区域在垂直方向上有序排列，确保界面整洁美观。
@Entry
@Component
struct TextExample7 {
  // 创建一个TextController实例，用于控制文本的选择和菜单的显示
  controller: TextController = new TextController();
  // 创建一个TextOptions实例，用于配置文本的控制器
  options: TextOptions = { controller: this.controller };

  build() {
    Column() {
      Column() {
        // 创建一个Text组件，内容为undefined，使用options配置
        Text(undefined, this.options) {
          // 创建一个Span组件，内容为"Hello World"
          Span('Hello World')
          // 创建一个ImageSpan组件，内容为应用内的图标资源
          ImageSpan($r('app.media.icon'))
            .width('100px') // 设置图像宽度为100px
            .height('100px') // 设置图像高度为100px
            .objectFit(ImageFit.Fill) // 设置图像填充方式为完全填充
            .verticalAlign(ImageSpanAlignment.CENTER) // 设置图像垂直对齐方式为居中
        }
        .copyOption(CopyOptions.InApp) // 设置文本的复制选项为仅在应用内复制
        .bindSelectionMenu(TextSpanType.IMAGE, this.LongPressImageCustomMenu, TextResponseType.LONG_PRESS, {
          onDisappear: () => {
            console.info(`自定义选择菜单关闭时回调`); // 自定义选择菜单关闭时的回调函数
          },
          onAppear: () => {
            console.info(`自定义选择菜单弹出时回调`); // 自定义选择菜单弹出时的回调函数
          }
        })
        .bindSelectionMenu(TextSpanType.TEXT, this.RightClickTextCustomMenu, TextResponseType.RIGHT_CLICK) // 绑定文本的右键点击菜单
        .bindSelectionMenu(TextSpanType.MIXED, this.SelectMixCustomMenu, TextResponseType.SELECT) // 绑定混合内容的选中菜单
        .onTextSelectionChange((selectionStart: number, selectionEnd: number) => {
          console.info(`文本选中区域变化回调, selectionStart: ${selectionStart}, selectionEnd: ${selectionEnd}`); // 文本选中区域变化时的回调函数
        })
        .borderWidth(1) // 设置边框宽度为1vp
        .borderColor(Color.Red) // 设置边框颜色为红色
        .width(200) // 设置宽度为200vp
        .height(100) // 设置高度为100vp
      }
      .width('100%') // 设置宽度为100%
      .backgroundColor(Color.White) // 设置背景颜色为白色
      .alignItems(HorizontalAlign.Start) // 设置对齐方式为左对齐
      .padding(25) // 设置内边距为25vp
    }
    .height('100%') // 设置高度为100%
  }

  // 定义右键点击文本时的自定义菜单
  @Builder
  RightClickTextCustomMenu() {
    Column() {
      Menu() {
        MenuItemGroup() {
          MenuItem({ startIcon: $r('app.media.app_icon'), content: "Right Click Menu 1", labelInfo: "" })
            .onClick((event) => {
              this.controller.closeSelectionMenu(); // 点击菜单项时关闭菜单
            })
          MenuItem({ startIcon: $r('app.media.app_icon'), content: "Right Click Menu 2", labelInfo: "" })
          MenuItem({ startIcon: $r('app.media.app_icon'), content: "Right Click Menu 3", labelInfo: "" })
        }
      }
      .MenuStyles() // 应用菜单样式
    }
  }

  // 定义长按图像时的自定义菜单
  @Builder
  LongPressImageCustomMenu() {
    Column() {
      Menu() {
        MenuItemGroup() {
          MenuItem({ startIcon: $r('app.media.app_icon'), content: "Long Press Image Menu 1", labelInfo: "" })
            .onClick((event) => {
              this.controller.closeSelectionMenu(); // 点击菜单项时关闭菜单
            })
          MenuItem({ startIcon: $r('app.media.app_icon'), content: "Long Press Image Menu 2", labelInfo: "" })
          MenuItem({ startIcon: $r('app.media.app_icon'), content: "Long Press Image Menu 3", labelInfo: "" })
        }
      }
      .MenuStyles() // 应用菜单样式
    }
  }

  // 定义选择混合内容时的自定义菜单
  @Builder
  SelectMixCustomMenu() {
    Column() {
      Menu() {
        MenuItemGroup() {
          MenuItem({ startIcon: $r('app.media.app_icon'), content: "Select Mixed Menu 1", labelInfo: "" })
            .onClick((event) => {
              this.controller.closeSelectionMenu(); // 点击菜单项时关闭菜单
            })
          MenuItem({ startIcon: $r('app.media.app_icon'), content: "Select Mixed Menu 2", labelInfo: "" })
          MenuItem({ startIcon: $r('app.media.app_icon'), content: "Select Mixed Menu 3", labelInfo: "" })
        }
      }
      .MenuStyles() // 应用菜单样式
    }
  }
}

