@Entry
@Component
struct TextExample5 {
  @State onCopy: string = '' // 存储复制的文本内容
  @State text: string = 'This is set selection to Selection text content This is set selection to Selection text content.' // 文本内容
  @State start: number = 0 // 文本选择的起始位置
  @State end: number = 20 // 文本选择的结束位置

  build() {
    Flex({ direction: FlexDirection.Column, alignItems: ItemAlign.Start, justifyContent: FlexAlign.Start }) {
      Text(this.text)
        .fontSize(12) // 设置字体大小为 12vp
        .border({ width: 1 }) // 设置边框宽度为 1vp
        .lineHeight(20) // 设置行高为 20vp
        .margin(30) // 设置外边距为 30vp
        .copyOption(CopyOptions.InApp) // 设置复制选项为仅在应用内复制
        .selection(this.start, this.end) // 设置文本选择的起始和结束位置
        .onCopy((value: string) => { // 当文本被复制时触发的事件
          this.onCopy = value // 将复制的文本内容存储到 onCopy 变量中
        })
      Button('Set text selection')
        .margin({left:20}) // 设置按钮的外边距为左 20vp
        .onClick(() => { // 按钮点击事件
          this.start = 10 // 设置文本选择的起始位置为 10
          this.end = 30 // 设置文本选择的结束位置为 30
        })
      Text(this.onCopy).fontSize(12).margin(10).key('copy') // 显示复制的文本内容，字体大小为 12vp，外边距为 10vp
    }.height(600).width(335).padding({ left: 35, right: 35, top: 35 }) // 设置布局的高度为 600vp，宽度为 335vp，内边距为左右 35vp、顶部 35vp
  }
}

