示例：该组件通过Flex布局实现了一个展示文本输入框及其相关属性的界面。布局宽度占据整个屏幕的90%，高度设为90%，内边距为左右10vp。组件的垂直方向上被分为三个部分，每个部分包含一个标题和一组文本输入框。每个文本输入框组的文本输入框以垂直布局方式排列，文本输入框之间的间距均匀分布，且对齐方式为居中对齐。
文本输入框的样式包括边框宽度、内边距、外边距、行高、字符间距和装饰线等属性，支持不同的样式展示。文本输入框组之间通过Flex组件进行分隔。文本输入框的功能包括显示不同的行高、字符间距和装饰线样式，用户可以通过输入框查看不同样式效果。
整个布局通过Flex布局保证文本输入框在垂直方向上有序排列，确保界面整洁美观。
@Entry
@Component
struct TextInputExample {
  build() {
    Row() {
      Column() {
        // 标题：行高
        Text('lineHeight').fontSize(9).fontColor(0xCCCCCC)
        // 文本输入框：未设置行高
        TextInput({text: 'lineHeight unset'})
          .border({ width: 1 }) // 设置边框宽度为1
          .padding(10) // 设置内边距为10
          .margin(5) // 设置外边距为5
        // 文本输入框：行高为15
        TextInput({text: 'lineHeight 15'})
          .border({ width: 1 }) // 设置边框宽度为1
          .padding(10) // 设置内边距为10
          .margin(5) // 设置外边距为5
          .lineHeight(15) // 设置行高为15
        // 文本输入框：行高为30
        TextInput({text: 'lineHeight 30'})
          .border({ width: 1 }) // 设置边框宽度为1
          .padding(10) // 设置内边距为10
          .margin(5) // 设置外边距为5
          .lineHeight(30) // 设置行高为30

        // 标题：字符间距
        Text('letterSpacing').fontSize(9).fontColor(0xCCCCCC)
        // 文本输入框：字符间距为0
        TextInput({text: 'letterSpacing 0'})
          .border({ width: 1 }) // 设置边框宽度为1
          .padding(5) // 设置内边距为5
          .margin(5) // 设置外边距为5
          .letterSpacing(0) // 设置字符间距为0
        // 文本输入框：字符间距为3
        TextInput({text: 'letterSpacing 3'})
          .border({ width: 1 }) // 设置边框宽度为1
          .padding(5) // 设置内边距为5
          .margin(5) // 设置外边距为5
          .letterSpacing(3) // 设置字符间距为3
        // 文本输入框：字符间距为-1
        TextInput({text: 'letterSpacing -1'})
          .border({ width: 1 }) // 设置边框宽度为1
          .padding(5) // 设置内边距为5
          .margin(5) // 设置外边距为5
          .letterSpacing(-1) // 设置字符间距为-1

        // 标题：装饰线
        Text('decoration').fontSize(9).fontColor(0xCCCCCC)
        // 文本输入框：装饰线为贯穿线，红色
        TextInput({text: 'LineThrough, Red'})
          .border({ width: 1 }) // 设置边框宽度为1
          .padding(5) // 设置内边距为5
          .margin(5) // 设置外边距为5
          .decoration({type: TextDecorationType.LineThrough, color: Color.Red}) // 设置装饰线为贯穿线，颜色为红色
        // 文本输入框：装饰线为上划线，红色，虚线
        TextInput({text: 'Overline, Red, DASHED'})
          .border({ width: 1 }) // 设置边框宽度为1
          .padding(5) // 设置内边距为5
          .margin(5) // 设置外边距为5
          .decoration({type: TextDecorationType.Overline, color: Color.Red, style: TextDecorationStyle.DASHED}) // 设置装饰线为上划线，颜色为红色，样式为虚线
        // 文本输入框：装饰线为下划线，红色，波浪线
        TextInput({text: 'Underline, Red, WAVY'})
          .border({ width: 1 }) // 设置边框宽度为1
          .padding(5) // 设置内边距为5
          .margin(5) // 设置外边距为5
          .decoration({type: TextDecorationType.Underline, color: Color.Red, style: TextDecorationStyle.WAVY}) // 设置装饰线为下划线，颜色为红色，样式为波浪线
      }.height('90%') // 设置列的高度为90%
    }
    .width('90%') // 设置行的宽度为90%
    .margin(10) // 设置行的外边距为10
  }
}

