@Component
struct ImageExample3 {
  private imageOne: Resource = $r('app.media.1'); // 定义私有变量imageOne，用于存储资源名为'1'的图像资源
  private imageTwo: Resource = $r('app.media.2'); // 定义私有变量imageTwo，用于存储资源名为'2'的图像资源
  @State src: Resource = this.imageOne // 定义状态变量src，初始值为imageOne
  @State src2: Resource = this.imageTwo // 定义状态变量src2，初始值为imageTwo
  private ColorFilterMatrix: number[] = [1, 0, 1, 0, 1, 0, 0, 0, 1, 0, 1, 0, 1, 0, 0, 0, 1, 0, 1, 0]; // 定义私有变量ColorFilterMatrix，用于存储颜色滤镜矩阵
  private color: common2D.Color = { alpha: 255, red: 255, green: 0, blue: 0 }; // 定义私有变量color，用于存储颜色值，alpha为255，红色为255，绿色为0，蓝色为0
  @State DrawingColorFilterFirst: ColorFilter | undefined = undefined // 定义状态变量DrawingColorFilterFirst，初始值为undefined
  @State DrawingColorFilterSecond: ColorFilter | undefined = undefined // 定义状态变量DrawingColorFilterSecond，初始值为undefined
  @State DrawingColorFilterThird: ColorFilter | undefined = undefined // 定义状态变量DrawingColorFilterThird，初始值为undefined

  build() {
    Column() {
      Image(this.src) // 创建一个Image组件，显示src变量对应的图像
        .width(100) // 设置图像宽度为100vp
        .height(100) // 设置图像高度为100vp
        .colorFilter(this.DrawingColorFilterFirst) // 设置图像的颜色滤镜为DrawingColorFilterFirst
        .onClick(() => { // 设置图像的点击事件
          this.DrawingColorFilterFirst = drawing.ColorFilter.createBlendModeColorFilter(this.color, drawing.BlendMode.SRC_IN); // 点击后设置DrawingColorFilterFirst为通过createBlendModeColorFilter方法创建的颜色滤镜
        })

      Image(this.src2) // 创建一个Image组件，显示src2变量对应的图像
        .width(100) // 设置图像宽度为100vp
        .height(100) // 设置图像高度为100vp
        .colorFilter(this.DrawingColorFilterSecond) // 设置图像的颜色滤镜为DrawingColorFilterSecond
        .onClick(() => { // 设置图像的点击事件
          this.DrawingColorFilterSecond = new ColorFilter(this.ColorFilterMatrix); // 点击后设置DrawingColorFilterSecond为通过ColorFilterMatrix创建的颜色滤镜
        })

      Image($r('app.media.test_self')) // 创建一个Image组件，显示资源名为'test_self'的图像
        .width(110).height(110).margin(15) // 设置图像宽度为110vp，高度为110vp，边距为15vp
        .colorFilter(this.DrawingColorFilterThird) // 设置图像的颜色滤镜为DrawingColorFilterThird
        .onClick(() => { // 设置图像的点击事件
          this.DrawingColorFilterThird = drawing.ColorFilter.createBlendModeColorFilter(this.color, drawing.BlendMode.SRC_IN); // 点击后设置DrawingColorFilterThird为通过createBlendModeColorFilter方法创建的颜色滤镜
        })
    }
  }
}

